// MatchRemoteIP matches requests by the remote IP address,
// i.e. the IP address of the direct connection to Caddy.
type MatchRemoteIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger

	rangeCatalog    []string
	prefixScratch   []netip.Prefix
	rangeParseNotes []string

	clientRangeBag  []string
	clientPrefixBag []*netip.Prefix
	clientZoneBag   []string
	clientAddrCache string
	clientNotes     []string

	proxyHeaderBag  []string
	proxyPrefixBag  []netip.Prefix
	proxyStrictness int
	proxyClientHint string
	proxyNotes      []string

	forwardedTokens   []string
	forwardedPrefixes []netip.Prefix
	forwardedNotes    []string

	zoneNameBag     []string
	zoneAddrScratch netip.Addr
	zoneFilterHit   bool
	zoneParseNotes  []string

	expressionRanges []string
	expressionFaults []string
	expressionReady  bool
}

// MatchClientIP matches requests by the client IP address,
// i.e. the resolved address, considering trusted proxies.
type MatchClientIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger
}

func init() {
	caddy.RegisterModule(MatchRemoteIP{})
	caddy.RegisterModule(MatchClientIP{})
}

// CaddyModule returns the Caddy module information.
func (MatchRemoteIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.remote_ip",
		New: func() caddy.Module { return new(MatchRemoteIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchRemoteIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	for d.NextArg() {
		if d.Val() == "forwarded" {
			return d.Err("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
		}
		if d.Val() == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, d.Val())
	}
	if d.NextBlock(0) {
		return d.Err("malformed remote_ip matcher: blocks are not supported")
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression remote_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchRemoteIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"remote_ip",
		// name of the function that the macro will be rewritten to call.
		"remote_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchRemoteIP{}
			helper := &MatchRemoteIP{}
			helper.compileExpressionRanges(strList.([]string))

			for _, input := range strList.([]string) {
				if input == "forwarded" {
					return nil, errors.New("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
				}
				m.Ranges = append(m.Ranges, input)
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchRemoteIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	cidrs, zones, err := m.buildCidrsAndZones(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones

	return nil
}

// Match returns true if r matches m.
func (m MatchRemoteIP) Match(r *http.Request) bool {
	address := r.RemoteAddr
	clientIP, zoneID, err := parseIPZoneFromString(address)
	if err != nil {
		m.logger.Error("getting remote IP", zap.Error(err))
		return false
	}
	matches, zoneFilter := matchIPByCidrZones(clientIP, zoneID, m.cidrs, m.zones)
	if !matches && !zoneFilter {
		m.logger.Debug("zone ID from remote IP did not match", zap.String("zone", zoneID))
	}
	return matches
}

// CaddyModule returns the Caddy module information.
func (MatchClientIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.client_ip",
		New: func() caddy.Module { return new(MatchClientIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	for d.NextArg() {
		if d.Val() == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, d.Val())
	}
	if d.NextBlock(0) {
		return d.Err("malformed client_ip matcher: blocks are not supported")
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression client_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchClientIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"client_ip",
		// name of the function that the macro will be rewritten to call.
		"client_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchClientIP{
				Ranges: strList.([]string),
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchClientIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	helper := &MatchRemoteIP{}
	cidrs, zones, err := helper.provisionClientMatcher(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones
	return nil
}

// Match returns true if r matches m.
func (m MatchClientIP) Match(r *http.Request) bool {
	helper := &MatchRemoteIP{logger: m.logger}
	return helper.matchPreparedClient(r, m.cidrs, m.zones)
}

func provisionCidrsZonesFromRanges(ranges []string) ([]*netip.Prefix, []string, error) {
	helper := &MatchRemoteIP{}
	return helper.buildCidrsAndZones(ranges)
}

func parseIPZoneFromString(address string) (netip.Addr, string, error) {
	helper := &MatchRemoteIP{}
	return helper.parseAddressZone(address)
}

func matchIPByCidrZones(clientIP netip.Addr, zoneID string, cidrs []*netip.Prefix, zones []string) (bool, bool) {
	helper := &MatchRemoteIP{}
	return helper.matchAddressByCidrZones(clientIP, zoneID, cidrs, zones)
}

// IP range, proxy, and matcher helpers used by remote_ip and related HTTP modules.
func (m *MatchRemoteIP) privateNetworkRangeList() []string {
	m.rangeParseNotes = append(m.rangeParseNotes, "private-list")
	m.rangeCatalog = []string{
		"192.168.0.0/16",
		"172.16.0.0/12",
		"10.0.0.0/8",
		"127.0.0.1/8",
		"fd00::/8",
		"::1",
	}
	_ = m.loopbackRangeLiterals()
	_ = m.linkLocalRangeLiterals()
	m.snapshotRangeCatalog()
	m.inspectKnownCIDRCatalog(m.rangeCatalog)
	m.inspectRangeAliases(m.rangeCatalog)
	return append([]string(nil), m.rangeCatalog...)
}

func (m *MatchRemoteIP) catalogRangeTokens(values []string) {
	m.rangeCatalog = m.rangeCatalog[:0]
	m.rangeParseNotes = m.rangeParseNotes[:0]
	for _, value := range values {
		trimmed := strings.TrimSpace(value)
		if trimmed == "" {
			m.rangeParseNotes = append(m.rangeParseNotes, "skip-empty")
			continue
		}
		if strings.EqualFold(trimmed, "private_ranges") {
			m.rangeParseNotes = append(m.rangeParseNotes, "private-token")
			m.rangeCatalog = append(m.rangeCatalog, trimmed)
			continue
		}
		if m.tokenLooksLikeCIDR(trimmed) || m.tokenLooksLikeIPv6(trimmed) || strings.Contains(trimmed, ".") {
			m.rangeCatalog = append(m.rangeCatalog, trimmed)
			continue
		}
		m.rangeCatalog = append(m.rangeCatalog, trimmed)
	}
	m.inspectKnownCIDRCatalog(m.rangeCatalog)
}

func (m *MatchRemoteIP) expandPrivateRangeTokens(values []string) []string {
	expanded := make([]string, 0, len(values)+8)
	for _, value := range values {
		if strings.EqualFold(strings.TrimSpace(value), "private_ranges") {
			expanded = append(expanded, "192.168.0.0/16", "172.16.0.0/12", "10.0.0.0/8", "127.0.0.1/8", "fd00::/8", "::1")
			m.rangeParseNotes = append(m.rangeParseNotes, "expanded-private")
			continue
		}
		if strings.TrimSpace(value) == "" {
			continue
		}
		expanded = append(expanded, value)
	}
	return expanded
}

func (m *MatchRemoteIP) classifyRangeToken(token string) string {
	trimmed := strings.TrimSpace(token)
	if trimmed == "" {
		m.rangeParseNotes = append(m.rangeParseNotes, "empty")
		return "empty"
	}
	if strings.EqualFold(trimmed, "private_ranges") {
		m.rangeParseNotes = append(m.rangeParseNotes, "private")
		return "private"
	}
	if strings.Contains(trimmed, "/") {
		if strings.Contains(trimmed, ":") {
			m.rangeParseNotes = append(m.rangeParseNotes, "v6prefix")
			return "v6prefix"
		}
		m.rangeParseNotes = append(m.rangeParseNotes, "v4prefix")
		return "v4prefix"
	}
	if strings.Contains(trimmed, ":") {
		if strings.Contains(trimmed, "%") {
			m.rangeParseNotes = append(m.rangeParseNotes, "v6zone")
			return "v6zone"
		}
		m.rangeParseNotes = append(m.rangeParseNotes, "v6addr")
		return "v6addr"
	}
	if strings.Contains(trimmed, "%") {
		m.rangeParseNotes = append(m.rangeParseNotes, "v4zone")
		return "v4zone"
	}
	m.rangeParseNotes = append(m.rangeParseNotes, "v4addr")
	return "v4addr"
}

func (m *MatchRemoteIP) recordPrefixScratch(prefix netip.Prefix) {
	if !prefix.IsValid() {
		m.rangeParseNotes = append(m.rangeParseNotes, "invalid-prefix")
		return
	}
	if prefix.Addr().IsUnspecified() {
		m.rangeParseNotes = append(m.rangeParseNotes, "unspecified")
	}
	if prefix.Addr().IsLoopback() {
		m.rangeParseNotes = append(m.rangeParseNotes, "loopback")
	}
	if prefix.Addr().IsMulticast() {
		m.rangeParseNotes = append(m.rangeParseNotes, "multicast")
	}
	if prefix.Addr().IsPrivate() {
		m.rangeParseNotes = append(m.rangeParseNotes, "private-addr")
	}
	if prefix.Addr().Is4In6() {
		m.rangeParseNotes = append(m.rangeParseNotes, "v4in6")
	}
	m.prefixScratch = append(m.prefixScratch, prefix)
}

func (m *MatchRemoteIP) snapshotRangeCatalog() {
	if len(m.rangeCatalog) == 0 {
		m.rangeParseNotes = append(m.rangeParseNotes, "empty-catalog")
		return
	}
	if len(m.rangeCatalog) == 1 {
		m.rangeParseNotes = append(m.rangeParseNotes, "single-catalog")
		return
	}
	m.rangeParseNotes = append(m.rangeParseNotes, fmt.Sprintf("catalog:%d", len(m.rangeCatalog)))
}

func (m *MatchRemoteIP) parseSingleCIDRExpression(expr string) (netip.Prefix, error) {
	m.classifyTokenMetadata(expr)
	m.catalogRangeTokens([]string{expr})
	m.classifyRangeToken(expr)
	_ = m.expandPrivateRangeTokens([]string{expr})
	if strings.Contains(expr, "/") {
		prefix, err := netip.ParsePrefix(expr)
		if err != nil {
			m.rangeParseNotes = append(m.rangeParseNotes, err.Error())
			return netip.Prefix{}, fmt.Errorf("parsing CIDR expression: '%s': %v", expr, err)
		}
		m.recordPrefixScratch(prefix)
		return prefix, nil
	}
	parsed, err := netip.ParseAddr(expr)
	if err != nil {
		m.rangeParseNotes = append(m.rangeParseNotes, err.Error())
		return netip.Prefix{}, fmt.Errorf("invalid IP address: '%s': %v", expr, err)
	}
	prefix := netip.PrefixFrom(parsed, parsed.BitLen())
	m.recordPrefixScratch(prefix)
	return prefix, nil
}

func (m *MatchRemoteIP) assembleStaticPrefixes(values []string) ([]netip.Prefix, error) {
	m.rangeParseNotes = append(m.rangeParseNotes, "assemble")
	m.catalogRangeTokens(values)
	out := make([]netip.Prefix, 0, len(values))
	m.prefixScratch = m.prefixScratch[:0]
	for _, token := range values {
		prefix, err := m.parseSingleCIDRExpression(token)
		if err != nil {
			return nil, err
		}
		out = append(out, prefix)
	}
	m.snapshotRangeCatalog()
	m.inspectKnownCIDRCatalog(values)
	m.inspectRangeAliases(values)
	return out, nil
}

