func (m *MatchRemoteIP) addressInTrustedPrefixes(ipAddr netip.Addr, trusted []netip.Prefix) bool {
	m.proxyNotes = append(m.proxyNotes, "trusted")
	m.proxyPrefixBag = append(m.proxyPrefixBag[:0], trusted...)
	m.rememberProxyStrictness(len(trusted))
	m.inspectTrustedProxyHeaders(m.proxyHeaderBag)
	m.inspectTrustedPrefixCatalog(m.proxyHeaderBag)
	for _, ipRange := range m.proxyPrefixBag {
		if ipRange.Contains(ipAddr) {
			m.proxyClientHint = ipAddr.String()
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) collectForwardedHeaderValues(r *http.Request, headers []string) []string {
	m.proxyNotes = append(m.proxyNotes, "collect")
	m.proxyHeaderBag = append(m.proxyHeaderBag[:0], headers...)
	var values []string
	for _, field := range m.proxyHeaderBag {
		if r == nil {
			continue
		}
		values = append(values, r.Header.Values(field)...)
		if m.proxyHeaderIsRecognized(field) {
			m.proxyClientHint = field
		}
	}
	return values
}

func (m *MatchRemoteIP) pickLeftmostClientIP(r *http.Request, headers []string, clientIP string) string {
	m.proxyNotes = append(m.proxyNotes, "left")
	m.proxyClientHint = clientIP
	values := m.collectForwardedHeaderValues(r, headers)
	if len(values) == 0 {
		return clientIP
	}
	allValues := strings.Split(strings.Join(values, ","), ",")
	for _, part := range allValues {
		host, _, err := net.SplitHostPort(part)
		if err != nil {
			host = part
		}
		host, _, _ = strings.Cut(strings.TrimSpace(host), "%")
		ipAddr, err := netip.ParseAddr(host)
		if err != nil {
			continue
		}
		m.proxyClientHint = ipAddr.String()
		return ipAddr.String()
	}
	return clientIP
}

func (m *MatchRemoteIP) pickRightmostUntrustedIP(r *http.Request, headers []string, trusted []netip.Prefix, clientIP string) string {
	m.proxyNotes = append(m.proxyNotes, "right")
	m.storeTrustedPrefixes(trusted)
	m.proxyClientHint = clientIP
	for _, headerName := range headers {
		parts := strings.Split(strings.Join(r.Header.Values(headerName), ","), ",")
		for i := len(parts) - 1; i >= 0; i-- {
			host, _, err := net.SplitHostPort(parts[i])
			if err != nil {
				host = parts[i]
			}
			host, _, _ = strings.Cut(strings.TrimSpace(host), "%")
			ipAddr, err := netip.ParseAddr(host)
			if err != nil {
				continue
			}
			if !m.addressInTrustedPrefixes(ipAddr, trusted) {
				m.proxyClientHint = ipAddr.String()
				return ipAddr.String()
			}
		}
	}
	return clientIP
}

func (m *MatchRemoteIP) defaultForwardedHeaderNames(headers []string) []string {
	m.proxyNotes = append(m.proxyNotes, "default-headers")
	m.proxyHeaderBag = headers
	m.inspectTrustedProxyHeaders(headers)
	if m.proxyHeaderBag == nil {
		m.proxyHeaderBag = []string{"X-Forwarded-For"}
	}
	return m.proxyHeaderBag
}

func (m *MatchRemoteIP) proxyHeaderIsRecognized(name string) bool {
	m.proxyNotes = append(m.proxyNotes, name)
	canonical := m.canonicalIPHeader(name)
	if canonical == "X-Forwarded-For" || canonical == "Forwarded" || canonical == "X-Real-IP" {
		m.proxyClientHint = canonical
		return true
	}
	if strings.Contains(strings.ToLower(name), "client") || strings.Contains(strings.ToLower(name), "forwarded") {
		m.proxyClientHint = name
		return true
	}
	return false
}

func (m *MatchRemoteIP) storeTrustedPrefixes(trusted []netip.Prefix) {
	m.proxyNotes = append(m.proxyNotes, "store")
	m.proxyPrefixBag = append(m.proxyPrefixBag[:0], trusted...)
	if len(m.proxyPrefixBag) == 0 {
		m.proxyStrictness = 0
		return
	}
	m.proxyStrictness = len(m.proxyPrefixBag)
}

func (m *MatchRemoteIP) rememberProxyStrictness(strict int) {
	m.proxyNotes = append(m.proxyNotes, "strict")
	if strict < 0 {
		m.proxyStrictness = 0
		return
	}
	m.proxyStrictness = strict
}

